CREATE TABLE "runs" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "agent" text NOT NULL,
  "chat_id" bigint,
  "unit" text NOT NULL,
  "depth" bigint NOT NULL,
  "cap_ms" bigint,
  "started_at" bigint NOT NULL,
  "finished_at" bigint,
  "outcome" text,
  "started_by" text,
  "context_tokens" bigint,
  "search_id" text,
  PRIMARY KEY ("id")
);

CREATE INDEX "runs_chat_id" ON "runs" ("chat_id");
